eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   categories: () => (/* binding */ categories),\n/* harmony export */   getTopicById: () => (/* binding */ getTopicById),\n/* harmony export */   topics: () => (/* binding */ topics)\n/* harmony export */ });\nconst topics = [\n    {\n        id: 'anxiety-and-panic',\n        title: 'Anxiety & Panic: When Your Body Sounds a False Alarm',\n        subtitle: 'Understanding the physical machinery of fear — and how to turn the volume down.',\n        category: 'Anxiety & Panic',\n        tone: 'sky',\n        icon: 'wind',\n        keywords: [\n            'anxiety',\n            'panic attack',\n            'worry',\n            'racing heart',\n            'avoidance',\n            'GAD'\n        ],\n        readingTime: 9,\n        featuredImage: \"/6f1a0d9f-8579-46cc-ac9d-c99dc170b4df.jpg\",\n        excerpt: 'A panic attack is not a heart attack, and chronic worry is not a character flaw. Here is what your nervous system is actually doing, and what reliably calms it.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Anxiety is the body preparing for a threat that has not arrived. That preparation is not imaginary — the heart really does beat faster, the chest really does tighten, thinking really does narrow. What is inaccurate is the size of the threat, not the sensation.',\n            'Roughly one in five adults lives with an anxiety condition in any given year. It is the most common and most treatable group of mental health conditions, and most people improve substantially with 8–16 weeks of structured therapy.'\n        ],\n        mechanics: {\n            heading: 'What is happening in your body',\n            body: [\n                'The amygdala flags something as dangerous and triggers a surge of adrenaline before the thinking brain has weighed in. Blood is redirected to large muscles, breathing quickens to load oxygen, and digestion slows. This is why anxiety so often shows up as nausea, cold hands, or a racing pulse.',\n                'A panic attack is that surge at full volume. It peaks around ten minutes and cannot physically sustain itself — the body runs out of adrenaline. Knowing the ceiling exists is itself a form of relief: the sensation is intense, self-limiting, and not dangerous.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Racing or pounding heart',\n                description: 'Often the first thing noticed, and frequently mistaken for a cardiac event.',\n                kind: 'Body'\n            },\n            {\n                label: 'Shallow chest breathing',\n                description: 'Rapid upper-chest breaths that create light-headedness and tingling fingers.',\n                kind: 'Body'\n            },\n            {\n                label: 'Catastrophic forecasting',\n                description: 'The mind jumps to the worst outcome and treats it as the likely one.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Quiet avoidance',\n                description: 'Declining plans, delaying calls, or leaving early — relief now, more fear later.',\n                kind: 'Behavior'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Panic attacks mean something is medically wrong with your heart.',\n                fact: 'Once a clinician has ruled out cardiac causes, panic symptoms are a stress response — uncomfortable and not physically harmful.'\n            },\n            {\n                myth: 'If I avoid what scares me, the anxiety will fade.',\n                fact: 'Avoidance teaches the brain the threat was real. Gradual, supported exposure is what lowers the alarm long term.'\n            },\n            {\n                myth: 'Anxious people just need to relax more.',\n                fact: 'Relaxation helps in the moment but does not retrain threat prediction. That takes structured practice, and often therapy.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'The 5-4-3-2-1 grounding scan',\n                summary: 'Interrupts the spiral by handing your attention something concrete to do.',\n                steps: [\n                    'Name five things you can see, out loud or silently.',\n                    'Name four things you can physically feel — fabric, chair, floor.',\n                    'Name three things you can hear, starting with the furthest away.',\n                    'Name two things you can smell, then one thing you can taste.'\n                ]\n            },\n            {\n                name: 'Extended exhale breathing',\n                summary: 'A longer exhale activates the vagus nerve and lowers heart rate within a minute or two.',\n                steps: [\n                    'Breathe in through the nose for a count of four.',\n                    'Hold gently for seven — no straining.',\n                    'Exhale through the mouth for eight, as if fogging a window.',\n                    'Repeat four cycles, then check in with your body.'\n                ]\n            },\n            {\n                name: 'Scheduled worry window',\n                summary: 'Contains rumination instead of fighting it, which frees the rest of the day.',\n                steps: [\n                    'Pick the same 15 minutes each day, not close to bedtime.',\n                    'When a worry arrives outside the window, write one line and defer it.',\n                    'In the window, write each worry and one next action — or mark it unsolvable.',\n                    'Close the notebook when time is up, even mid-thought.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Cognitive Behavioural Therapy',\n                abbreviation: 'CBT',\n                description: 'The best-evidenced treatment for anxiety. Identifies the thought–feeling–behaviour loop and rebuilds it with gradual exposure.'\n            },\n            {\n                name: 'Acceptance & Commitment Therapy',\n                abbreviation: 'ACT',\n                description: 'Reduces the struggle against anxious sensations and reorients daily choices around values rather than fear.'\n            },\n            {\n                name: 'Medical consultation',\n                abbreviation: 'MD',\n                description: 'A physician can rule out thyroid, cardiac, and medication causes, and discuss SSRIs or short-term options where appropriate.'\n            }\n        ],\n        support: {\n            guidance: 'You do not need to argue someone out of anxiety. Your job is to be a steady, unhurried presence — slow your own speech, stay physically near, and let the peak pass without adding pressure.',\n            say: [\n                '“I am here. We can just sit until this passes.”',\n                '“Nothing you feel right now needs explaining to me.”',\n                '“Do you want company, quiet, or some air?”'\n            ],\n            avoid: [\n                '“Calm down — there is nothing to worry about.”',\n                '“Just stop thinking about it.”',\n                '“Other people have it much worse.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Is medication a last resort?',\n                answer: 'No. Medication is one legitimate option among several, often used alongside therapy. The decision belongs to you and a prescribing clinician, not to a hierarchy of willpower.'\n            },\n            {\n                question: 'How long until therapy helps?',\n                answer: 'Most people notice a measurable shift in 6–8 sessions of CBT, with larger gains by 12–16. Progress is usually gradual rather than a single breakthrough.'\n            },\n            {\n                question: 'Will this website tell anyone I read it?',\n                answer: 'No. We store nothing about you — no account, no IP log, no analytics. Reading this page leaves no trace on our side.'\n            }\n        ],\n        pacer: [\n            {\n                label: '4-7-8 calming',\n                inhale: 4,\n                hold: 7,\n                exhale: 8,\n                description: 'The default. Longest exhale, strongest downshift — best for acute spikes.'\n            },\n            {\n                label: 'Box breathing',\n                inhale: 4,\n                hold: 4,\n                exhale: 4,\n                description: 'Even and steady. Easier to hold for longer stretches before a stressful event.'\n            }\n        ]\n    },\n    {\n        id: 'depression',\n        title: 'Depression: When the Volume of Everything Drops',\n        subtitle: 'Why motivation disappears before mood recovers, and how to work with that order.',\n        category: 'Depression',\n        tone: 'lavender',\n        icon: 'cloudRain',\n        keywords: [\n            'depression',\n            'low mood',\n            'anhedonia',\n            'motivation',\n            'hopelessness',\n            'MDD'\n        ],\n        readingTime: 8,\n        featuredImage: \"/bbd80de0-72e7-4a34-bead-99f81d08bcba.jpg\",\n        excerpt: 'Depression is not sadness turned up. It is a flattening of reward, energy, and self-narrative — and it responds to action taken before the motivation returns.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'People often expect depression to feel like crying. More often it feels like nothing: food without taste, music without pull, a to-do list that may as well be in another language.',\n            'That absence is a symptom, not a personality. Depression narrows the brain’s reward signalling, so activities that used to pay off no longer register — which makes withdrawal feel rational and deepens the loop.'\n        ],\n        mechanics: {\n            heading: 'Why willpower is the wrong lever',\n            body: [\n                'In depression, the anticipation of reward dims before the capacity for it does. You can still enjoy a walk; you simply cannot feel in advance that you would. Waiting to feel like it means waiting for the last symptom to lift first.',\n                'This is why behavioural activation works: small scheduled actions taken without motivation slowly restore the reward signal. Mood follows movement rather than leading it.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Loss of interest',\n                description: 'Things that reliably mattered — people, work, food — go flat. Clinicians call this anhedonia.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Leaden fatigue',\n                description: 'Sleep does not restore. Ordinary tasks cost several times their usual energy.',\n                kind: 'Body'\n            },\n            {\n                label: 'Harsh self-narration',\n                description: 'A running commentary of burden, failure, and worthlessness that feels factual.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Withdrawal from contact',\n                description: 'Cancelling, leaving messages unread, shrinking the day down to survival.',\n                kind: 'Behavior'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Depression is caused by a simple chemical imbalance.',\n                fact: 'It involves biology, stress, sleep, circumstance, and thought patterns together. Treatment works on several of those at once.'\n            },\n            {\n                myth: 'If you can work and smile, it is not real depression.',\n                fact: 'High-functioning depression is common. Capability at work says nothing about internal cost.'\n            },\n            {\n                myth: 'You have to want to get better first.',\n                fact: 'Ambivalence is a symptom. Treatment can begin while hope is still absent.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Behavioural activation ladder',\n                summary: 'Builds momentum from actions small enough to be undeniable.',\n                steps: [\n                    'List activities that used to matter, ranked by effort.',\n                    'Schedule the two easiest at fixed times tomorrow.',\n                    'Do them at the scheduled time regardless of mood.',\n                    'Rate mood before and after — collect evidence, not opinions.'\n                ]\n            },\n            {\n                name: 'The two-minute floor',\n                summary: 'Removes the negotiation about whether today is a good enough day.',\n                steps: [\n                    'Choose one anchor task: teeth, shower, one glass of water, one open window.',\n                    'Commit to two minutes, with permission to stop after.',\n                    'Do it at the same time daily so it stops requiring a decision.'\n                ]\n            },\n            {\n                name: 'Thought-record reframing',\n                summary: 'Separates a feeling from a verdict about who you are.',\n                steps: [\n                    'Write the thought verbatim, including the cruelty.',\n                    'Note the evidence for it, then the evidence against it.',\n                    'Write a version you would say to someone you respect.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Cognitive Behavioural Therapy',\n                abbreviation: 'CBT',\n                description: 'Targets the thought patterns and withdrawal that maintain low mood; strongest evidence base for mild to moderate depression.'\n            },\n            {\n                name: 'Behavioural Activation',\n                abbreviation: 'BA',\n                description: 'A focused, structured therapy that rebuilds daily activity and reward. Often effective when energy is the main barrier.'\n            },\n            {\n                name: 'Medication review',\n                abbreviation: 'MD',\n                description: 'Antidepressants can help moderate to severe depression, usually within 4–6 weeks. A prescriber should also check thyroid, iron, and vitamin D.'\n            }\n        ],\n        support: {\n            guidance: 'Offer specific, low-effort presence rather than open-ended invitations. “Let me know if you need anything” asks a depressed person to do the organising. Bring the plan with you.',\n            say: [\n                '“I am bringing dinner Thursday at seven. You do not have to talk.”',\n                '“You are not a burden to me. I am choosing to be here.”',\n                '“Would it help if I made the appointment call with you?”'\n            ],\n            avoid: [\n                '“You have so much to be grateful for.”',\n                '“Have you tried exercising more?”',\n                '“Snap out of it — this isn’t you.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Should I push someone to socialise?',\n                answer: 'Invite gently and repeatedly without penalty for declining. Pressure adds guilt; a standing, no-obligation invitation keeps the door open.'\n            },\n            {\n                question: 'When is it urgent?',\n                answer: 'If someone mentions wanting to die, giving possessions away, or has a plan, treat it as urgent. Stay with them and call or text 988 together.'\n            },\n            {\n                question: 'Can depression lift on its own?',\n                answer: 'Some episodes remit without treatment, but untreated episodes tend to be longer and more likely to recur. Treatment shortens and softens them.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Gentle 4-4-6',\n                inhale: 4,\n                hold: 4,\n                exhale: 6,\n                description: 'A low-effort pace for days when even breathing exercises feel like work.'\n            },\n            {\n                label: '4-7-8 calming',\n                inhale: 4,\n                hold: 7,\n                exhale: 8,\n                description: 'Use when low mood arrives with agitation or a tight chest.'\n            }\n        ]\n    },\n    {\n        id: 'burnout-and-stress',\n        title: 'Burnout & Chronic Stress: The Cost of Running Without Recovery',\n        subtitle: 'Exhaustion, cynicism, and dwindling effectiveness — and how to reverse them.',\n        category: 'Burnout & Stress',\n        tone: 'sand',\n        icon: 'batteryLow',\n        keywords: [\n            'burnout',\n            'stress',\n            'overwork',\n            'exhaustion',\n            'boundaries',\n            'cynicism'\n        ],\n        readingTime: 7,\n        featuredImage: \"/bc248231-c940-4e95-a939-9f1a54a31f7a.jpg\",\n        excerpt: 'Burnout is an occupational condition with three measurable dimensions. Rest alone will not fix it — the demands and the recovery both have to change.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Burnout is not simply being tired. The World Health Organization defines it as a syndrome from chronic workplace stress that has not been successfully managed, with three parts: exhaustion, mental distance or cynicism, and reduced effectiveness.',\n            'Naming all three matters. People often try to solve burnout with a holiday, then feel defeated when the cynicism returns in week one. Exhaustion responds to rest; the other two respond to changes in demand, control, and meaning.'\n        ],\n        mechanics: {\n            heading: 'Why a weekend does not reset it',\n            body: [\n                'Under sustained load, cortisol regulation shifts. Recovery becomes slower and less complete, so each week starts from a deficit. The body adapts by lowering engagement — that flatness is protective, not lazy.',\n                'Genuine recovery needs both a reduction in demand and active restoration: sleep, movement, connection, and time where no one needs anything from you. One without the other stalls.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Sunday-night dread',\n                description: 'Anticipatory tension that arrives before the week does.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Tension headaches and jaw clenching',\n                description: 'Muscular holding patterns that persist into evenings and sleep.',\n                kind: 'Body'\n            },\n            {\n                label: 'Compassion fatigue',\n                description: 'Caring feels expensive, so distance replaces it — often with guilt attached.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Task paralysis',\n                description: 'Staring at a short list, unable to start, then working late to compensate.',\n                kind: 'Behavior'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Burnout means you are not resilient enough.',\n                fact: 'Burnout is a property of workload and conditions, not of character. Resilience training alone does not fix an unmanageable job.'\n            },\n            {\n                myth: 'A vacation will fix burnout.',\n                fact: 'Time off relieves exhaustion temporarily. Without changes to demand or control, symptoms typically return within weeks.'\n            },\n            {\n                myth: 'Only caring professions burn out.',\n                fact: 'It occurs in any role with high demand and low autonomy, including creative, technical, and unpaid caregiving work.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Boundary script templates',\n                summary: 'Pre-written language makes saying no possible in the moment.',\n                steps: [\n                    '“I can take this on if we move X — which would you prefer?”',\n                    '“I am at capacity this week. I can start Monday.”',\n                    '“I am offline after 18:30. I will pick this up first thing.”',\n                    'Send without apologising or over-explaining.'\n                ]\n            },\n            {\n                name: 'Recovery audit',\n                summary: 'Distinguishes real restoration from numbing that leaves you tired.',\n                steps: [\n                    'For one week, log what you do after work and how you feel an hour later.',\n                    'Mark each entry restorative, neutral, or depleting.',\n                    'Replace one depleting habit with a restorative one at the same time slot.'\n                ]\n            },\n            {\n                name: 'Shutdown ritual',\n                summary: 'Gives the nervous system a clear end-of-day signal.',\n                steps: [\n                    'Write tomorrow’s three priorities before closing anything.',\n                    'Close every tab and app, out loud if it helps.',\n                    'Change clothes or walk once around the block to mark the transition.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Cognitive Behavioural Therapy',\n                abbreviation: 'CBT',\n                description: 'Addresses perfectionism, over-responsibility, and the beliefs that make boundaries feel dangerous.'\n            },\n            {\n                name: 'Acceptance & Commitment Therapy',\n                abbreviation: 'ACT',\n                description: 'Clarifies values so work choices stop being driven by obligation, and builds tolerance for the discomfort of saying no.'\n            },\n            {\n                name: 'Occupational health review',\n                abbreviation: 'OH',\n                description: 'A clinician can document capacity, recommend adjustments, and rule out anaemia, thyroid issues, or sleep apnoea.'\n            }\n        ],\n        support: {\n            guidance: 'Resist the urge to optimise their calendar. Someone in burnout has already heard every productivity tip. Offer to absorb load instead, and be specific about what you will take.',\n            say: [\n                '“What is one thing I can take off your plate this week?”',\n                '“You are allowed to be this tired.”',\n                '“I will handle dinner and the school run Thursday.”'\n            ],\n            avoid: [\n                '“Everyone is busy right now.”',\n                '“Maybe you just need better time management.”',\n                '“At least you have a job.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Is burnout a medical diagnosis?',\n                answer: 'It is classified as an occupational phenomenon rather than a medical condition, but it frequently coexists with depression or anxiety, which are diagnosable and treatable.'\n            },\n            {\n                question: 'Do I need to quit my job?',\n                answer: 'Rarely the first step. Changes to workload, autonomy, and recovery resolve many cases. If conditions cannot change, a longer-term plan may be needed.'\n            },\n            {\n                question: 'How long does recovery take?',\n                answer: 'Mild burnout often improves in weeks once demands drop. Severe, long-standing burnout commonly takes several months of sustained change.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Box breathing',\n                inhale: 4,\n                hold: 4,\n                exhale: 4,\n                description: 'Steady and repeatable — good between meetings or before a difficult conversation.'\n            },\n            {\n                label: 'Long 4-2-8 exhale',\n                inhale: 4,\n                hold: 2,\n                exhale: 8,\n                description: 'For the end of the day, when the body needs a clear signal to stand down.'\n            }\n        ]\n    },\n    {\n        id: 'trauma-and-ptsd',\n        title: 'Trauma & PTSD: When the Past Keeps Arriving in the Present',\n        subtitle: 'Flashbacks, hypervigilance, and numbing are protection, not malfunction.',\n        category: 'Trauma & PTSD',\n        tone: 'lavender',\n        icon: 'shieldAlert',\n        keywords: [\n            'trauma',\n            'PTSD',\n            'flashback',\n            'hypervigilance',\n            'triggers',\n            'EMDR'\n        ],\n        readingTime: 9,\n        featuredImage: \"/ff47f82f-c7ed-4863-b7ca-fd3bac014a4a.jpg\",\n        excerpt: 'Trauma is stored differently from ordinary memory, which is why it returns as sensation rather than story. Grounding and trauma-focused therapy both work with that.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'A traumatic memory is not filed the way other memories are. Under extreme threat, the brain prioritises survival over narrative, so fragments — a smell, a tone of voice, a body position — get stored without a timestamp.',\n            'When a fragment is triggered later, the body responds as if the event is happening now. That is what makes flashbacks so disorienting: the experience is real, but the clock is wrong.'\n        ],\n        mechanics: {\n            heading: 'Threat memory without a timestamp',\n            body: [\n                'Hypervigilance, startle responses, and numbing are all downstream of a threat-detection system that has raised its baseline. Nothing is broken; the setting is simply stuck on high after it was genuinely needed.',\n                'Grounding works by giving the brain unambiguous present-tense evidence — cold water, textured objects, naming the year out loud. Trauma-focused therapy then helps the memory be re-filed with its correct date attached.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Intrusive re-experiencing',\n                description: 'Images, sounds, or bodily sensations that arrive uninvited and feel current.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Startle and scanning',\n                description: 'Sitting facing exits, jumping at doors, exhausting alertness in safe rooms.',\n                kind: 'Body'\n            },\n            {\n                label: 'Emotional numbing',\n                description: 'Feeling distant from people and from yourself, as if behind glass.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Trigger avoidance',\n                description: 'Routing around places, media, or conversations, gradually shrinking daily life.',\n                kind: 'Behavior'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Only combat veterans get PTSD.',\n                fact: 'Assault, accidents, medical events, childbirth, childhood neglect, and sustained abuse can all cause PTSD.'\n            },\n            {\n                myth: 'Talking about it always makes it worse.',\n                fact: 'Unstructured retelling can overwhelm, but structured trauma-focused therapy is what most reliably reduces symptoms.'\n            },\n            {\n                myth: 'If it happened long ago, it should be over.',\n                fact: 'Untreated trauma has no expiry date. Symptoms can surface decades later, often after a period of apparent stability.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Orienting to the present',\n                summary: 'Reasserts the correct date and place when a flashback begins.',\n                steps: [\n                    'Say the year, month, and your age out loud.',\n                    'Name five objects in the room and one thing you can hear.',\n                    'Press your feet into the floor and feel the chair behind you.',\n                    'Add temperature — cold water on the wrists or a cold glass in hand.'\n                ]\n            },\n            {\n                name: 'Window-of-tolerance check',\n                summary: 'Names your current state so you can choose the right tool.',\n                steps: [\n                    'Rate arousal now: shut down, settled, or over-activated.',\n                    'If over-activated, use long exhales and cold sensation.',\n                    'If shut down, use gentle movement, standing, or a bilateral tap.'\n                ]\n            },\n            {\n                name: 'Safety-anchor kit',\n                summary: 'Puts grounding within reach before it is needed.',\n                steps: [\n                    'Assemble a strong scent, a textured object, and headphones.',\n                    'Add a card with three phrases that reliably help you.',\n                    'Keep one kit at home and a small version in a bag.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Eye Movement Desensitisation & Reprocessing',\n                abbreviation: 'EMDR',\n                description: 'Uses bilateral stimulation while recalling the memory so it can be reprocessed with far less physiological charge.'\n            },\n            {\n                name: 'Trauma-Focused CBT',\n                abbreviation: 'TF-CBT',\n                description: 'Combines gradual, controlled exposure with cognitive work on guilt, blame, and safety beliefs.'\n            },\n            {\n                name: 'Somatic and body-based therapy',\n                abbreviation: 'SE',\n                description: 'Works with the nervous system directly — useful when talking triggers overwhelm or memory is fragmentary.'\n            }\n        ],\n        support: {\n            guidance: 'Predictability is the whole job. Announce changes, avoid surprise touch, and let them keep control of doors, exits, and pace. You are not there to retrieve details.',\n            say: [\n                '“You are safe here. It is 2026 and you are in your kitchen.”',\n                '“Do you want me closer or a little further away?”',\n                '“You never have to tell me what happened.”'\n            ],\n            avoid: [\n                '“What exactly happened to you?”',\n                '“You need to move on from this.”',\n                '“It couldn’t have been that bad.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Can PTSD be treated successfully?',\n                answer: 'Yes. EMDR and trauma-focused CBT produce substantial improvement for most people, often within 8–20 sessions.'\n            },\n            {\n                question: 'What if I cannot remember it clearly?',\n                answer: 'Fragmentary memory is typical and does not disqualify you from treatment. Therapies work with the fragments and the body’s response.'\n            },\n            {\n                question: 'Is it normal to feel nothing at all?',\n                answer: 'Yes. Numbing is one of the recognised symptom clusters, and it often lifts as safety is re-established.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Gentle 4-4-6',\n                inhale: 4,\n                hold: 4,\n                exhale: 6,\n                description: 'Short holds. Long breath-holding can feel unsafe when trauma is active.'\n            },\n            {\n                label: 'Even 5-0-5',\n                inhale: 5,\n                hold: 0,\n                exhale: 5,\n                description: 'No hold at all — continuous, predictable rhythm for grounding.'\n            }\n        ]\n    },\n    {\n        id: 'grief-and-loss',\n        title: 'Grief & Loss: Carrying What Cannot Be Fixed',\n        subtitle: 'Grief is not a staircase you climb. It is weather you learn to live inside.',\n        category: 'Grief & Loss',\n        tone: 'blush',\n        icon: 'heartCrack',\n        keywords: [\n            'grief',\n            'bereavement',\n            'loss',\n            'mourning',\n            'anniversary',\n            'death'\n        ],\n        readingTime: 7,\n        featuredImage: \"/89ea5304-a8bb-41e5-9dea-1e2b10aaa20c.jpg\",\n        excerpt: 'The five stages were never meant as a sequence. Modern grief care focuses on oscillation — moving between loss and life — rather than on reaching acceptance.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Grief is not only about death. It follows divorce, diagnosis, estrangement, miscarriage, and the loss of a future you had assumed. Any of those can produce the full physical weight of mourning.',\n            'The five-stage model was originally observed in dying patients, not the bereaved, and was never intended as a checklist. Grief does not progress tidily, and revisiting an earlier feeling is not regression.'\n        ],\n        mechanics: {\n            heading: 'Oscillation, not stages',\n            body: [\n                'Current models describe grief as moving back and forth between confronting the loss and attending to ongoing life. Both are necessary. A morning of laughter does not undo mourning, and a wave of sorrow two years on is not a relapse.',\n                'Grief also lives in the body: appetite changes, disrupted sleep, chest heaviness, and a real hit to concentration and immune function. This is why practical care — food, water, sleep — is legitimate grief work.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Waves rather than a slope',\n                description: 'Intensity arrives suddenly, often triggered by something small and ordinary.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Physical heaviness',\n                description: 'Chest pressure, aching limbs, and exhaustion that sleep does not touch.',\n                kind: 'Body'\n            },\n            {\n                label: 'Searching behaviour',\n                description: 'Scanning crowds, rereading messages, keeping a phone number active.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Guilt and rehearsal',\n                description: 'Replaying what might have been said or done differently.',\n                kind: 'Mind'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Grief lasts about a year.',\n                fact: 'There is no schedule. Acute grief often softens over months, but adaptation continues for years and anniversaries stay tender.'\n            },\n            {\n                myth: 'Staying busy is the healthiest approach.',\n                fact: 'Distraction has a place, but grief that is never approached tends to surface as physical symptoms or sudden collapse.'\n            },\n            {\n                myth: 'Moving forward means letting go.',\n                fact: 'Most people keep a continuing bond with the person they lost. Integration, not erasure, is the goal.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Continuing-bond letters',\n                summary: 'Keeps the relationship present in a form you control.',\n                steps: [\n                    'Write to them, not about them — present tense.',\n                    'Include ordinary news, not only sorrow.',\n                    'Stop when it becomes heavy; there is no requirement to finish.'\n                ]\n            },\n            {\n                name: 'Anniversary planning',\n                summary: 'Removes the dread of being ambushed by a date.',\n                steps: [\n                    'Mark the date and decide in advance who you want nearby.',\n                    'Choose one small ritual — a walk, a meal they loved, a candle.',\n                    'Give yourself explicit permission to cancel everything else.'\n                ]\n            },\n            {\n                name: 'Baseline care card',\n                summary: 'Reduces daily decisions to a short, achievable list.',\n                steps: [\n                    'Write four items: water, one meal, outside air, one message answered.',\n                    'Keep it visible in the kitchen.',\n                    'Treat a partly ticked card as a completed day.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Grief-focused counselling',\n                abbreviation: 'GC',\n                description: 'Individual or group support that normalises the process and helps rebuild routine and identity after a loss.'\n            },\n            {\n                name: 'Complicated Grief Treatment',\n                abbreviation: 'CGT',\n                description: 'A structured therapy for prolonged grief disorder, where intense yearning persists past twelve months and blocks daily function.'\n            },\n            {\n                name: 'Medical review',\n                abbreviation: 'MD',\n                description: 'Useful when sleep, appetite, or chest symptoms persist, both to treat them and to rule out physical causes.'\n            }\n        ],\n        support: {\n            guidance: 'Say the person’s name. Grieving people are usually more afraid of the loss being forgotten than of being reminded of it. Show up on the ordinary Tuesday, not only at the funeral.',\n            say: [\n                '“I remember when she used to do this — I still think about it.”',\n                '“I have no words that help, but I am not going anywhere.”',\n                '“I am coming over Saturday to do the laundry, not to talk.”'\n            ],\n            avoid: [\n                '“They are in a better place now.”',\n                '“Everything happens for a reason.”',\n                '“At least you had many years together.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'When is grief a clinical concern?',\n                answer: 'If after twelve months there is persistent, intense yearning with an inability to function, prolonged grief disorder may apply and specific treatment helps.'\n            },\n            {\n                question: 'Should children attend a funeral?',\n                answer: 'Usually yes, if they want to and are prepared for what they will see. Exclusion tends to increase confusion rather than reduce distress.'\n            },\n            {\n                question: 'Why do I feel relief alongside sorrow?',\n                answer: 'Relief is extremely common, especially after long illness or a difficult relationship. It coexists with love rather than contradicting it.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Even 5-0-5',\n                inhale: 5,\n                hold: 0,\n                exhale: 5,\n                description: 'No hold — useful when crying makes breath-holding uncomfortable.'\n            },\n            {\n                label: 'Gentle 4-4-6',\n                inhale: 4,\n                hold: 4,\n                exhale: 6,\n                description: 'For the tight-chested moments that arrive without warning.'\n            }\n        ]\n    },\n    {\n        id: 'sleep-and-insomnia',\n        title: 'Sleep & Insomnia: Getting Out of Your Own Way at 3 a.m.',\n        subtitle: 'Why trying harder to sleep keeps you awake, and what actually retrains the system.',\n        category: 'Sleep',\n        tone: 'sky',\n        icon: 'moon',\n        keywords: [\n            'insomnia',\n            'sleep',\n            'racing thoughts',\n            'CBT-I',\n            'sleep hygiene',\n            'waking'\n        ],\n        readingTime: 7,\n        featuredImage: \"/e4423b3d-c70b-425e-b57a-69877c5c940e.jpg\",\n        excerpt: 'Chronic insomnia is maintained less by the original trigger than by what we do about it. CBT-I outperforms sleeping medication over the long term.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Almost everyone sleeps badly sometimes. Insomnia becomes chronic when the response to a bad night — earlier bedtimes, longer lie-ins, more effort — accidentally weakens the link between bed and sleep.',\n            'Sleep cannot be produced by effort. It arrives when pressure to sleep is high and arousal is low, which is why the most effective treatment reduces time in bed rather than increasing it.'\n        ],\n        mechanics: {\n            heading: 'Sleep pressure and the alerting system',\n            body: [\n                'Two systems govern sleep: homeostatic pressure that builds the longer you are awake, and a circadian clock that sets the window. Napping and long lie-ins spend pressure early, leaving too little for the night.',\n                'Lying awake for hours also conditions the bed as a place of vigilance. Getting up when awake, and keeping a fixed wake time, rebuilds the association within a few weeks.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Racing thoughts at lights-out',\n                description: 'The first quiet moment of the day becomes the mind’s processing window.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Early-hours waking',\n                description: 'Waking at 3 a.m. fully alert, often with a surge of dread.',\n                kind: 'Body'\n            },\n            {\n                label: 'Clock-watching',\n                description: 'Calculating remaining sleep, which raises arousal and delays it further.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Daytime fog',\n                description: 'Slowed thinking, irritability, and low tolerance for minor stress.',\n                kind: 'Mind'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Everyone needs exactly eight hours.',\n                fact: 'Healthy adult need ranges roughly from seven to nine hours. Daytime function matters more than the number.'\n            },\n            {\n                myth: 'Lying in bed still counts as rest.',\n                fact: 'Extended wakeful time in bed strengthens insomnia. Getting up briefly is more effective than waiting it out.'\n            },\n            {\n                myth: 'Alcohol helps you sleep.',\n                fact: 'It shortens sleep onset but fragments the second half of the night and suppresses restorative REM sleep.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Stimulus control',\n                summary: 'Restores the bed as a cue for sleep rather than for vigilance.',\n                steps: [\n                    'If awake for more than 20 minutes, get up.',\n                    'Sit somewhere dim and do something undemanding.',\n                    'Return only when sleepy, not merely tired.',\n                    'Keep the same wake time regardless of how the night went.'\n                ]\n            },\n            {\n                name: 'Constructive worry',\n                summary: 'Moves the mind’s processing window out of the bedroom.',\n                steps: [\n                    'Ninety minutes before bed, list tomorrow’s concerns.',\n                    'Write one next action beside each.',\n                    'Close the notebook — the list will still exist in the morning.'\n                ]\n            },\n            {\n                name: 'Light and temperature anchoring',\n                summary: 'Gives the circadian clock the two signals it responds to most.',\n                steps: [\n                    'Get outdoor light within an hour of waking.',\n                    'Dim household lighting for the last ninety minutes of the evening.',\n                    'Keep the bedroom cool — around 18°C is a common optimum.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'CBT for Insomnia',\n                abbreviation: 'CBT-I',\n                description: 'The first-line treatment. Combines sleep restriction, stimulus control, and cognitive work; effects outlast medication.'\n            },\n            {\n                name: 'Sleep study assessment',\n                abbreviation: 'PSG',\n                description: 'Recommended when snoring, gasping, or unrefreshing sleep suggest apnoea or a movement disorder.'\n            },\n            {\n                name: 'Short-term medication',\n                abbreviation: 'MD',\n                description: 'Occasionally appropriate for brief, acute insomnia, with a clear stopping plan agreed in advance.'\n            }\n        ],\n        support: {\n            guidance: 'Do not ask how they slept first thing — it turns sleep into a daily performance review. Support the daytime routine instead, especially morning light and a fixed wake time.',\n            say: [\n                '“Want to walk with me this morning? The light helps.”',\n                '“A bad night doesn’t mean tomorrow is ruined.”',\n                '“I can take the early shift so you can keep your wake time.”'\n            ],\n            avoid: [\n                '“You just need to go to bed earlier.”',\n                '“Have you tried simply not thinking?”',\n                '“You looked exhausted all day.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'How long does CBT-I take?',\n                answer: 'Typically four to eight sessions, with noticeable change by week three. Digital programmes show similar results to in-person delivery.'\n            },\n            {\n                question: 'Are naps always bad?',\n                answer: 'A single nap before 3 p.m. and under 20 minutes is usually fine. Longer or later naps spend the sleep pressure you need at night.'\n            },\n            {\n                question: 'What about melatonin?',\n                answer: 'Most useful for circadian shifts such as jet lag, at low doses and timed correctly. It is not a sedative and rarely fixes chronic insomnia alone.'\n            }\n        ],\n        pacer: [\n            {\n                label: '4-7-8 calming',\n                inhale: 4,\n                hold: 7,\n                exhale: 8,\n                description: 'The classic pre-sleep pace. Use lying down with the lights off.'\n            },\n            {\n                label: 'Long 4-2-8 exhale',\n                inhale: 4,\n                hold: 2,\n                exhale: 8,\n                description: 'For 3 a.m. waking with a racing heart.'\n            }\n        ]\n    },\n    {\n        id: 'loneliness',\n        title: 'Loneliness: The Gap Between Contact and Connection',\n        subtitle: 'You can be surrounded by people and still unmet. That gap is measurable — and closable.',\n        category: 'Loneliness',\n        tone: 'sand',\n        icon: 'users',\n        keywords: [\n            'loneliness',\n            'isolation',\n            'connection',\n            'belonging',\n            'friendship',\n            'social'\n        ],\n        readingTime: 6,\n        featuredImage: \"/24be4b57-e071-4f09-9726-22df0281e8d1.jpg\",\n        excerpt: 'Loneliness is a signal, like hunger. It responds less to more socialising than to a small number of interactions with real depth.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Loneliness is the felt distance between the connection you have and the connection you need. It is about quality, which is why it survives busy calendars and crowded offices.',\n            'It also has a physical cost. Sustained loneliness is associated with disrupted sleep, elevated inflammation, and higher cardiovascular risk — comparable in scale to well-known lifestyle risks.'\n        ],\n        mechanics: {\n            heading: 'Why loneliness protects itself',\n            body: [\n                'Prolonged loneliness raises social threat sensitivity. Neutral faces read as cold, delayed replies read as rejection, and withdrawal starts to feel like the safer option.',\n                'Breaking that loop rarely means becoming more outgoing. It means small, repeated, low-stakes contact with the same people — the ingredient that turns acquaintance into familiarity.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Feeling unseen in company',\n                description: 'Present at the table but unknown at it — the loneliest version of loneliness.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Rejection forecasting',\n                description: 'Assuming you would be a burden, so the invitation never gets sent.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Restless evenings',\n                description: 'Scrolling, snacking, or bingeing to fill a specific kind of quiet.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Fragmented sleep',\n                description: 'Loneliness reliably lightens sleep, an old vigilance response to being alone.',\n                kind: 'Body'\n            }\n        ],\n        myths: [\n            {\n                myth: 'Loneliness means you are socially unskilled.',\n                fact: 'It is a common response to transition — a move, a breakup, a new job, new parenthood. Skills are usually intact.'\n            },\n            {\n                myth: 'More social events will fix it.',\n                fact: 'Volume rarely helps. Depth and repetition with a few people do.'\n            },\n            {\n                myth: 'Only isolated older people feel it.',\n                fact: 'Rates are highest in young adults. Living with others is no protection.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'The one-degree deeper question',\n                summary: 'Turns pleasantries into contact without demanding vulnerability.',\n                steps: [\n                    'Follow any small-talk answer with one genuine question about it.',\n                    'Offer one real detail about yourself in return.',\n                    'Stop there. Depth builds across conversations, not within one.'\n                ]\n            },\n            {\n                name: 'Repeat-exposure anchors',\n                summary: 'Uses regularity to build familiarity with no invitation required.',\n                steps: [\n                    'Choose one weekly place: a class, a shift, a court, a choir.',\n                    'Attend the same session for six weeks before judging it.',\n                    'Greet the same person each time — that is the whole task.'\n                ]\n            },\n            {\n                name: 'Low-stakes reach-out template',\n                summary: 'Removes the effort of composing a message from scratch.',\n                steps: [\n                    '“Thought of you — remember this?” with a photo or link.',\n                    '“No agenda. How is the new place treating you?”',\n                    'Send three on the same day so no single reply carries the weight.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Cognitive Behavioural Therapy',\n                abbreviation: 'CBT',\n                description: 'Most effective loneliness intervention in trials — targets the social threat expectations that drive withdrawal.'\n            },\n            {\n                name: 'Group therapy',\n                abbreviation: 'GT',\n                description: 'Provides connection and practice simultaneously, with a facilitator to make the interaction safe.'\n            },\n            {\n                name: 'Social prescribing',\n                abbreviation: 'SP',\n                description: 'A clinician or link worker connects you to community activity matched to your interests and capacity.'\n            }\n        ],\n        support: {\n            guidance: 'Be the one who follows up. Lonely people often stop initiating because they expect to be declined. Consistency reads as evidence far more than any single warm conversation.',\n            say: [\n                '“I am putting a standing walk in the calendar for Sundays.”',\n                '“I noticed you went quiet. I am checking in, not chasing.”',\n                '“I would like to know how you actually are.”'\n            ],\n            avoid: [\n                '“You should get out more.”',\n                '“But you have so many friends!”',\n                '“Just download an app and meet people.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Is loneliness the same as depression?',\n                answer: 'No, though they overlap and each raises the risk of the other. Loneliness is about connection; depression affects mood, energy, and reward broadly.'\n            },\n            {\n                question: 'How long does it take to make a real friend?',\n                answer: 'Research suggests roughly 50 hours of shared time for casual friendship and considerably more for close friendship. Slowness is normal, not failure.'\n            },\n            {\n                question: 'Does online contact count?',\n                answer: 'Yes, when it involves real exchange with people who know you. Passive scrolling of others’ lives tends to deepen loneliness.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Box breathing',\n                inhale: 4,\n                hold: 4,\n                exhale: 4,\n                description: 'Steadying before sending a message or walking into a room.'\n            },\n            {\n                label: 'Gentle 4-4-6',\n                inhale: 4,\n                hold: 4,\n                exhale: 6,\n                description: 'For the heavy part of the evening, when the quiet gets loud.'\n            }\n        ]\n    },\n    {\n        id: 'ocd',\n        title: 'OCD: The Trap of Certainty',\n        subtitle: 'Compulsions work briefly, which is exactly why the doubt keeps returning.',\n        category: 'OCD',\n        tone: 'mist',\n        icon: 'repeat',\n        keywords: [\n            'OCD',\n            'obsessions',\n            'compulsions',\n            'intrusive thoughts',\n            'ERP',\n            'checking'\n        ],\n        readingTime: 8,\n        featuredImage: \"/3014125d-fa77-4475-ad19-6fa3c021102a.jpg\",\n        excerpt: 'OCD is not tidiness. It is a cycle of intrusive doubt and relief-seeking, and it responds to a specific, well-evidenced therapy.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'OCD has two parts: obsessions, which are unwanted intrusive thoughts, images, or urges, and compulsions, which are the things done to make the discomfort stop.',\n            'Intrusive thoughts themselves are universal. What distinguishes OCD is the meaning attached to them — the sense that having the thought says something about who you are, and that certainty must be obtained.'\n        ],\n        mechanics: {\n            heading: 'The relief that feeds the loop',\n            body: [\n                'A compulsion works. Checking the lock, seeking reassurance, or repeating a phrase genuinely lowers anxiety in the moment, which teaches the brain that the danger was real and the ritual saved you.',\n                'Exposure and Response Prevention breaks that lesson. You approach the trigger and deliberately do not perform the ritual, so the brain learns that discomfort falls on its own. Anxiety habituates; certainty never arrives, and stops being required.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Taboo intrusive thoughts',\n                description: 'Violent, sexual, or blasphemous content that is deeply distressing and contrary to your values.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Checking and repeating',\n                description: 'Locks, appliances, emails, or re-reading — never producing lasting certainty.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Reassurance seeking',\n                description: 'Asking the same question of loved ones or search engines in different wording.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Mental rituals',\n                description: 'Counting, praying, reviewing memories — invisible from outside and just as exhausting.',\n                kind: 'Mind'\n            }\n        ],\n        myths: [\n            {\n                myth: 'OCD means liking things clean and organised.',\n                fact: 'Contamination is only one theme. Many people with OCD have no cleaning rituals at all, and the condition is distressing rather than satisfying.'\n            },\n            {\n                myth: 'Intrusive thoughts reveal hidden desires.',\n                fact: 'The opposite. OCD fixates on what you find most abhorrent, which is why the thoughts cause so much distress.'\n            },\n            {\n                myth: 'Reassuring someone helps them.',\n                fact: 'Reassurance is a compulsion by proxy. It relieves the moment and strengthens the cycle.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Delay and reduce',\n                summary: 'A gentle entry point to response prevention when full ERP feels impossible.',\n                steps: [\n                    'When the urge arrives, set a timer for ten minutes.',\n                    'Notice the anxiety rise and then fall without the ritual.',\n                    'If you still perform it, reduce it — check once, not six times.',\n                    'Extend the delay each week.'\n                ]\n            },\n            {\n                name: 'Labelling the mechanism',\n                summary: 'Separates the thought from your identity.',\n                steps: [\n                    'Say “this is an OCD thought,” not “I am having a terrible thought.”',\n                    'Do not argue with the content or seek proof.',\n                    'Return attention to whatever you were doing, unfinished feeling included.'\n                ]\n            },\n            {\n                name: 'Uncertainty tolerance practice',\n                summary: 'Trains the skill OCD attacks — living without a guarantee.',\n                steps: [\n                    'Choose one small daily uncertainty: send an email unproofed twice.',\n                    'Sit with the discomfort and log its intensity at 0, 10, and 30 minutes.',\n                    'Review the log weekly to see habituation as data.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Exposure & Response Prevention',\n                abbreviation: 'ERP',\n                description: 'The gold-standard treatment. Structured exposure to triggers while resisting compulsions, guided by a trained therapist.'\n            },\n            {\n                name: 'Medication',\n                abbreviation: 'SSRI',\n                description: 'Often at higher doses than for depression, and typically most effective when combined with ERP.'\n            },\n            {\n                name: 'Acceptance & Commitment Therapy',\n                abbreviation: 'ACT',\n                description: 'Used alongside ERP to reduce fusion with intrusive thoughts and reconnect action with values.'\n            }\n        ],\n        support: {\n            guidance: 'Stop participating in rituals, kindly and with warning. Agree in advance how you will respond to reassurance requests, so declining feels like a shared plan rather than a rejection.',\n            say: [\n                '“I love you, and we agreed I would not answer that one.”',\n                '“I can sit with you while the urge passes.”',\n                '“The thought is not you. It is the OCD talking.”'\n            ],\n            avoid: [\n                '“I promise nothing bad will happen.”',\n                '“Just stop thinking about it.”',\n                '“I wish I were as organised as you.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Is ERP dangerous or traumatic?',\n                answer: 'No. Exposures are graded, collaborative, and always chosen by you. A good therapist never forces a step you have not agreed to.'\n            },\n            {\n                question: 'Does OCD ever go away completely?',\n                answer: 'Many people reach the point where symptoms no longer shape their life. Occasional flares are common, especially under stress, and respond quickly to booster ERP.'\n            },\n            {\n                question: 'What if my theme feels too shameful to say?',\n                answer: 'Clinicians who treat OCD have heard every theme. Naming it is usually the moment the shame starts to lose its grip.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Box breathing',\n                inhale: 4,\n                hold: 4,\n                exhale: 4,\n                description: 'For riding out an urge — steady, countable, and finite.'\n            },\n            {\n                label: '4-7-8 calming',\n                inhale: 4,\n                hold: 7,\n                exhale: 8,\n                description: 'After an exposure, to help the body come back down.'\n            }\n        ]\n    },\n    {\n        id: 'substance-use',\n        title: 'Substance Use: Beyond Willpower and Rock Bottom',\n        subtitle: 'Change rarely begins with a dramatic moment. It begins with ambivalence taken seriously.',\n        category: 'Substance Use',\n        tone: 'mist',\n        icon: 'pillBottle',\n        keywords: [\n            'substance use',\n            'alcohol',\n            'addiction',\n            'recovery',\n            'relapse',\n            'harm reduction'\n        ],\n        readingTime: 8,\n        featuredImage: \"/2c24f0fa-868a-4068-8e48-996bef5a7078.jpg\",\n        excerpt: 'Substance use disorders are treatable medical conditions. Confrontation and ultimatums predict worse outcomes than curiosity and access to care.',\n        reviewer: 'Reviewed by Dr. Skelton',\n        updated: 'Updated August 2026',\n        intro: [\n            'Substance use exists on a spectrum, and a diagnosis rests on the impact on your life — health, relationships, obligations — not on how much you consume relative to others.',\n            'Repeated use changes reward, stress, and impulse-control circuits, which is why stopping is not a straightforward matter of resolve. That is a description of a mechanism, not an excuse.'\n        ],\n        mechanics: {\n            heading: 'Craving, cues, and the stress loop',\n            body: [\n                'Cues — a time of day, a route home, a particular feeling — trigger craving faster than conscious thought. Cravings usually peak and subside within about twenty minutes, which makes surfing them a realistic skill.',\n                'Withdrawal from alcohol and benzodiazepines can be medically dangerous and should never be attempted alone. A prescriber can make it safe with a supervised plan.'\n            ]\n        },\n        symptoms: [\n            {\n                label: 'Rising tolerance',\n                description: 'Needing more for the same effect, often noticed before anything else.',\n                kind: 'Body'\n            },\n            {\n                label: 'Failed limits',\n                description: 'Repeated genuine attempts to cut down that do not hold.',\n                kind: 'Behavior'\n            },\n            {\n                label: 'Preoccupation',\n                description: 'Planning around access — how much is left, when the next chance comes.',\n                kind: 'Mind'\n            },\n            {\n                label: 'Narrowing life',\n                description: 'Interests, friendships, and obligations quietly making room for use.',\n                kind: 'Behavior'\n            }\n        ],\n        myths: [\n            {\n                myth: 'People must hit rock bottom before they change.',\n                fact: 'There is no clinical basis for this. Earlier intervention consistently predicts better outcomes; waiting mainly adds harm.'\n            },\n            {\n                myth: 'Relapse means treatment failed.',\n                fact: 'Relapse rates resemble other chronic conditions like diabetes or hypertension. It signals a plan needing adjustment, not a person who failed.'\n            },\n            {\n                myth: 'Tough love is the responsible approach.',\n                fact: 'Confrontation and shame increase concealment. Warmth plus clear boundaries and access to treatment works better.'\n            }\n        ],\n        strategies: [\n            {\n                name: 'Urge surfing',\n                summary: 'Uses the natural time limit of a craving instead of fighting it head-on.',\n                steps: [\n                    'Name it: “this is a craving, and it will crest.”',\n                    'Locate it physically — chest, throat, hands.',\n                    'Breathe with it for twenty minutes without acting.',\n                    'Note the peak time so you learn your own curve.'\n                ]\n            },\n            {\n                name: 'Cue mapping',\n                summary: 'Makes automatic triggers visible so they can be interrupted.',\n                steps: [\n                    'Log each urge with time, place, people, and feeling.',\n                    'After a week, circle the three strongest patterns.',\n                    'Change one concrete detail in each — the route, the hour, the glass.'\n                ]\n            },\n            {\n                name: 'Harm-reduction floor',\n                summary: 'Lowers risk immediately, whether or not you are ready to stop.',\n                steps: [\n                    'Never use alone; tell one person when and where.',\n                    'Keep naloxone accessible if opioids are involved.',\n                    'Set one measurable limit per occasion and write it down beforehand.'\n                ]\n            }\n        ],\n        treatments: [\n            {\n                name: 'Motivational Interviewing',\n                abbreviation: 'MI',\n                description: 'A collaborative conversation style that works with ambivalence rather than against it, often the effective first step.'\n            },\n            {\n                name: 'Medication for Addiction Treatment',\n                abbreviation: 'MAT',\n                description: 'Naltrexone, acamprosate, buprenorphine, and methadone substantially reduce craving and mortality. Evidence-based, not a substitute addiction.'\n            },\n            {\n                name: 'Cognitive Behavioural Therapy',\n                abbreviation: 'CBT',\n                description: 'Builds relapse-prevention skills, cue management, and coping alternatives for stress and low mood.'\n            }\n        ],\n        support: {\n            guidance: 'You can hold a firm boundary and stay warm at the same time. Boundaries protect you; warmth keeps the door open. Ultimatums delivered in anger usually cost both.',\n            say: [\n                '“I am worried about you, and I am not going anywhere.”',\n                '“I will drive you to the appointment and sit in the waiting room.”',\n                '“I will not cover for this, and I still love you.”'\n            ],\n            avoid: [\n                '“You are choosing this over your family.”',\n                '“If you loved me you would stop.”',\n                '“You have wasted everything.”'\n            ]\n        },\n        faqs: [\n            {\n                question: 'Is medication just swapping one drug for another?',\n                answer: 'No. Treatment medications stabilise brain chemistry at steady doses without intoxication, and they measurably reduce overdose deaths.'\n            },\n            {\n                question: 'Do I have to want to quit entirely?',\n                answer: 'Not to start. Many people begin with harm reduction or a reduction goal, and revise it as their situation and confidence change.'\n            },\n            {\n                question: 'Is withdrawal safe to do at home?',\n                answer: 'Alcohol and benzodiazepine withdrawal can cause seizures and can be fatal. Always speak to a prescriber before stopping abruptly.'\n            }\n        ],\n        pacer: [\n            {\n                label: 'Long 4-2-8 exhale',\n                inhale: 4,\n                hold: 2,\n                exhale: 8,\n                description: 'For riding out the twenty-minute peak of a craving.'\n            },\n            {\n                label: 'Box breathing',\n                inhale: 4,\n                hold: 4,\n                exhale: 4,\n                description: 'Countable and neutral — good in public or at work.'\n            }\n        ]\n    }\n];\nconst categories = [\n    'All Topics',\n    'Anxiety & Panic',\n    'Depression',\n    'Burnout & Stress',\n    'Trauma & PTSD',\n    'Grief & Loss',\n    'Sleep',\n    'Loneliness',\n    'OCD',\n    'Substance Use'\n];\nfunction getTopicById(id) {\n    return topics.find((topic)=>topic.id === id);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/topics.ts\n");

